// A9 thermal HAL: AIDL android.hardware.thermal V3 over the core in
// thermal_core.cpp. NDK backend generated by build.sh from the frozen V3 API.
// Reports temperatures, thresholds and cooling devices, notifies severity and
// cooling-state changes; never writes sysfs (kernel cooling-maps mitigate).
#include <aidl/android/hardware/thermal/BnThermal.h>
#include <android/binder_manager.h>
#include <android/binder_process.h>
#include <android/log.h>

#include <unistd.h>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <mutex>
#include <sstream>
#include <thread>

#include "thermal_core.h"

#define LOG_TAG "thermal-a9"
#define ALOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)
#define ALOGW(...) __android_log_print(ANDROID_LOG_WARN, LOG_TAG, __VA_ARGS__)
#define ALOGE(...) __android_log_print(ANDROID_LOG_ERROR, LOG_TAG, __VA_ARGS__)

using namespace aidl::android::hardware::thermal;
using ndk::ScopedAStatus;

namespace {

constexpr const char* kConf = "/vendor/etc/thermal-a9.conf";
constexpr int kAll = -2;   // no type filter (TemperatureType::UNKNOWN is -1)

int64_t nowMs() {
    using namespace std::chrono;
    return duration_cast<milliseconds>(steady_clock::now().time_since_epoch()).count();
}

class ThermalA9 : public BnThermal {
  public:
    explicit ThermalA9(a9thermal::Core core) : core_(std::move(core)) {}

    void start() {
        {
            std::lock_guard<std::mutex> l(m_);
            core_.poll(nowMs());
            core_.pollCooling();
            for (auto& s : core_.sensors())
                ALOGI("sensor %s -> %s (%s)", s.cfg.name.c_str(), s.last.valid ? s.last.path.c_str() : "absent",
                      s.last.valid ? std::to_string(s.last.celsius).c_str() : "-");
        }
        std::thread([this] { loop(); }).detach();
    }

    ScopedAStatus getCoolingDevices(std::vector<CoolingDevice>* out) override {
        return coolingWith(false, CoolingType::FAN, out);
    }
    ScopedAStatus getCoolingDevicesWithType(CoolingType t, std::vector<CoolingDevice>* out) override {
        return coolingWith(true, t, out);
    }
    ScopedAStatus getTemperatures(std::vector<Temperature>* out) override {
        return temps(false, TemperatureType::UNKNOWN, out);
    }
    ScopedAStatus getTemperaturesWithType(TemperatureType t, std::vector<Temperature>* out) override {
        return temps(true, t, out);
    }
    ScopedAStatus getTemperatureThresholds(std::vector<TemperatureThreshold>* out) override {
        return thresholds(false, TemperatureType::UNKNOWN, out);
    }
    ScopedAStatus getTemperatureThresholdsWithType(TemperatureType t,
                                                   std::vector<TemperatureThreshold>* out) override {
        return thresholds(true, t, out);
    }
    ScopedAStatus registerThermalChangedCallback(const std::shared_ptr<IThermalChangedCallback>& cb) override {
        return addCb(cb, false, TemperatureType::UNKNOWN);
    }
    ScopedAStatus registerThermalChangedCallbackWithType(const std::shared_ptr<IThermalChangedCallback>& cb,
                                                         TemperatureType t) override {
        return addCb(cb, true, t);
    }
    ScopedAStatus unregisterThermalChangedCallback(const std::shared_ptr<IThermalChangedCallback>& cb) override {
        if (!cb) return ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT);
        std::lock_guard<std::mutex> l(m_);
        size_t n = cbs_.size();
        cbs_.erase(std::remove_if(cbs_.begin(), cbs_.end(),
                                  [&](const Cb& c) { return c.cb->asBinder() == cb->asBinder(); }),
                   cbs_.end());
        return n == cbs_.size() ? ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT) : ScopedAStatus::ok();
    }
    ScopedAStatus registerCoolingDeviceChangedCallbackWithType(
            const std::shared_ptr<ICoolingDeviceChangedCallback>& cb, CoolingType t) override {
        if (!cb) return ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT);
        std::lock_guard<std::mutex> l(m_);
        for (auto& c : ccbs_)
            if (c.cb->asBinder() == cb->asBinder()) return ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT);
        ccbs_.push_back({cb, t});
        return ScopedAStatus::ok();
    }
    ScopedAStatus unregisterCoolingDeviceChangedCallback(
            const std::shared_ptr<ICoolingDeviceChangedCallback>& cb) override {
        if (!cb) return ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT);
        std::lock_guard<std::mutex> l(m_);
        size_t n = ccbs_.size();
        ccbs_.erase(std::remove_if(ccbs_.begin(), ccbs_.end(),
                                   [&](const CCb& c) { return c.cb->asBinder() == cb->asBinder(); }),
                    ccbs_.end());
        return n == ccbs_.size() ? ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT) : ScopedAStatus::ok();
    }
    ScopedAStatus forecastSkinTemperature(int32_t, float*) override {
        return ScopedAStatus::fromExceptionCode(EX_UNSUPPORTED_OPERATION);
    }

    binder_status_t dump(int fd, const char**, uint32_t) override {
        std::ostringstream o;
        std::lock_guard<std::mutex> l(m_);
        o << core_.dumpText();   // format parsed by thermal-gate.py (host-tested)
        o << "callbacks: " << cbs_.size() << " thermal, " << ccbs_.size() << " cooling\n";
        std::string s = o.str();
        ssize_t w = write(fd, s.data(), s.size());
        (void)w;
        return STATUS_OK;
    }

  private:
    struct Cb {
        std::shared_ptr<IThermalChangedCallback> cb;
        bool filtered;
        TemperatureType type;
    };
    struct CCb {
        std::shared_ptr<ICoolingDeviceChangedCallback> cb;
        CoolingType type;
    };

    static Temperature toTemp(const a9thermal::PubTemp& p) {
        Temperature t;
        t.type = static_cast<TemperatureType>(p.type);
        t.name = p.name;
        t.value = p.value;   // NAN while the sensor is faulty (AIDL: "not available")
        t.throttlingStatus = static_cast<ThrottlingSeverity>(p.severity);
        return t;
    }
    static Temperature toTemp(const a9thermal::SensorState& s) {
        return toTemp(a9thermal::PubTemp{s.cfg.name, s.cfg.type, s.last.valid ? s.last.celsius : NAN, s.severity});
    }

    // Listing contract (AIDL IThermal): a sensor/cooling device that existed is
    // never removed and keeps its order; thresholds are static. The core keeps
    // that state (Core::temperatures/thresholds/coolingDevices).
    ScopedAStatus temps(bool filtered, TemperatureType t, std::vector<Temperature>* out) {
        std::lock_guard<std::mutex> l(m_);
        out->clear();
        for (auto& p : core_.temperatures(filtered ? static_cast<int>(t) : kAll)) out->push_back(toTemp(p));
        return ScopedAStatus::ok();
    }

    ScopedAStatus thresholds(bool filtered, TemperatureType t, std::vector<TemperatureThreshold>* out) {
        std::lock_guard<std::mutex> l(m_);
        out->clear();
        for (auto& p : core_.thresholds(filtered ? static_cast<int>(t) : kAll)) {
            TemperatureThreshold th;
            th.type = static_cast<TemperatureType>(p.type);
            th.name = p.name;
            th.hotThrottlingThresholds.assign(p.hot, p.hot + a9thermal::kSeverities);
            th.coldThrottlingThresholds.assign(a9thermal::kSeverities, NAN);
            out->push_back(th);
        }
        return ScopedAStatus::ok();
    }

    ScopedAStatus coolingWith(bool filtered, CoolingType t, std::vector<CoolingDevice>* out) {
        std::lock_guard<std::mutex> l(m_);
        out->clear();
        for (auto& c : core_.coolingDevices(filtered ? static_cast<int>(t) : kAll)) {
            CoolingDevice d;
            d.type = static_cast<CoolingType>(c.type);
            d.name = c.name;
            d.value = c.cur;
            out->push_back(d);
        }
        return ScopedAStatus::ok();
    }

    ScopedAStatus addCb(const std::shared_ptr<IThermalChangedCallback>& cb, bool filtered, TemperatureType t) {
        if (!cb) return ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT);
        std::vector<Temperature> now;
        {
            std::lock_guard<std::mutex> l(m_);
            for (auto& c : cbs_)
                if (c.cb->asBinder() == cb->asBinder()) return ScopedAStatus::fromExceptionCode(EX_ILLEGAL_ARGUMENT);
            cbs_.push_back({cb, filtered, t});
            // report sensors that are already throttling (as the AOSP default HAL)
            for (auto& s : core_.sensors())
                if (s.last.valid && s.severity > 0 && (!filtered || static_cast<int>(t) == s.cfg.type))
                    now.push_back(toTemp(s));
        }
        for (auto& x : now) cb->notifyThrottling(x);
        return ScopedAStatus::ok();
    }

    void loop() {
        for (;;) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::vector<Temperature> changed;
            std::vector<CoolingDevice> cchanged;
            std::vector<Cb> cbs;
            std::vector<CCb> ccbs;
            {
                std::lock_guard<std::mutex> l(m_);
                for (size_t i : core_.poll(nowMs())) {
                    auto& s = core_.sensors()[i];
                    if (s.fault)
                        ALOGW("%s FAULT (%s): value NaN, severity %d", s.cfg.name.c_str(), s.faultWhy.c_str(), s.severity);
                    else
                        ALOGI("%s %.1f C -> severity %d", s.cfg.name.c_str(), s.last.celsius, s.severity);
                    changed.push_back(toTemp(s));
                }
                if (++coolTick_ >= 5) {
                    coolTick_ = 0;
                    for (auto& n : core_.pollCooling())
                        for (auto& c : core_.cooling())
                            if (c.name == n) {
                                CoolingDevice d;
                                d.type = static_cast<CoolingType>(c.type);
                                d.name = c.name;
                                d.value = c.cur;
                                cchanged.push_back(d);
                            }
                }
                cbs = cbs_;
                ccbs = ccbs_;
            }
            std::vector<AIBinder*> dead;
            for (auto& t : changed)
                for (auto& c : cbs)
                    if (!c.filtered || c.type == t.type)
                        if (!c.cb->notifyThrottling(t).isOk()) dead.push_back(c.cb->asBinder().get());
            for (auto& d : cchanged)
                for (auto& c : ccbs)
                    if (c.type == d.type)
                        if (!c.cb->notifyCoolingDeviceChanged(d).isOk()) dead.push_back(c.cb->asBinder().get());
            if (!dead.empty()) {
                std::lock_guard<std::mutex> l(m_);
                auto isDead = [&](AIBinder* b) { return std::find(dead.begin(), dead.end(), b) != dead.end(); };
                cbs_.erase(std::remove_if(cbs_.begin(), cbs_.end(),
                                          [&](const Cb& c) { return isDead(c.cb->asBinder().get()); }),
                           cbs_.end());
                ccbs_.erase(std::remove_if(ccbs_.begin(), ccbs_.end(),
                                           [&](const CCb& c) { return isDead(c.cb->asBinder().get()); }),
                            ccbs_.end());
            }
        }
    }

    std::mutex m_;
    a9thermal::Core core_;
    std::vector<Cb> cbs_;
    std::vector<CCb> ccbs_;
    int coolTick_ = 0;
};

}  // namespace

int main() {
    std::ifstream f(kConf);
    std::stringstream ss;
    ss << f.rdbuf();
    std::vector<a9thermal::SensorCfg> cfg;
    std::string err;
    if (!f || !a9thermal::parseConfig(ss.str(), &cfg, &err)) {
        ALOGE("%s: %s", kConf, f ? err.c_str() : "cannot open");
        return 1;
    }
    ABinderProcess_setThreadPoolMaxThreadCount(0);
    auto hal = ndk::SharedRefBase::make<ThermalA9>(a9thermal::Core(cfg, a9thermal::Sysfs()));
    hal->start();
    const std::string name = std::string() + IThermal::descriptor + "/default";
    binder_status_t st = AServiceManager_addService(hal->asBinder().get(), name.c_str());
    if (st != STATUS_OK) {
        ALOGE("addService %s failed: %d", name.c_str(), st);
        return 1;
    }
    ALOGI("%s registered, %zu sensors", name.c_str(), cfg.size());
    ABinderProcess_joinThreadPool();
    return 1;
}
